-- Migration 038: CEI2008 Esther repairs (#185). Generated by
-- scripts/repair_cei2008_esther.py from the bibbiaedu.it archive; see its
-- docstring for what each part does and why. Text © Fondazione di Religione
-- Santi Francesco d'Assisi e Caterina da Siena (bibbiaedu.it), reproduced
-- unaltered with attribution.
--
-- Replaces the text of 12 damaged rows (guarded on their current text),
-- inserts Est 8:2 (Greek and Hebrew) and Hebrew 9:30, rebuilds CEI2008 in
-- reading order, and updates CEI2008_idx for Esther. Idempotent: does
-- nothing once Hebrew 8:2 exists. Re-embed CEI2008 afterwards (both columns).

BEGIN;

CREATE TEMP TABLE cei_ord (vid INT PRIMARY KEY, ord NUMERIC NOT NULL) ON COMMIT DROP;

DO $mig$
DECLARE
    n       INT;
    changed INT := 0;
    anchor  INT;
    new_vid INT;
BEGIN
    IF EXISTS (SELECT 1 FROM "CEI2008" WHERE book = 19 AND chapter = 8 AND verse = 2 AND verseorigin = 'HEBREW') THEN
        RAISE NOTICE '038 already applied';
        RETURN;
    END IF;
    IF (SELECT count(*) FROM "CEI2008") <> 35720 THEN
        RAISE EXCEPTION 'CEI2008 has % rows, expected 35720', (SELECT count(*) FROM "CEI2008");
    END IF;

    UPDATE "CEI2008" SET text = 'l''anno terzo del suo regno fece un banchetto per gli amici e per quelli delle altre nazionalità, per i nobili dei Persiani e dei Medi e per i prefetti delle province.', embedding = NULL WHERE "verseID" = 13479 AND text = 'l''anno terzo del suo regno fece un banchetto per gli amici e per quelli delle altre nazionalità, per i nobili dei Persiani e i dei Medi e per i prefetti delle province.';  -- Est 1:3 GREEK
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'passati questi giorni il re fece un altro banchetto di sette giorni, nel cortile del giardino della reggia, per tutto il popolo che si trovava nella cittadella di Susa, dal più grande al più piccolo.', embedding = NULL WHERE "verseID" = 13299 AND text = 'passati questi giorni il re fece un altro banchetto di sette giorni, nel cortile del giardino della reggia, per tutto il popolo che si trovava nella cittadella di Susa, dal più grande al più piccolo. Vi erano cortine di lino fine e di porpora viola, sospese con cordoni di bisso e di porpora rossa ad anelli d''argento e a colonne di marmo bianco; vi erano inoltre divani d''oro e d''argento sopra un pavimento di marmo verde, bianco e di madreperla e di pietre a colori.';  -- Est 1:5 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = '<pof>Il re disse: "Convocate subito Aman, per fare ciò che Ester ha detto".</pof>
<pol>Il re andò dunque con Aman al banchetto che Ester aveva preparato.</pol>', embedding = NULL WHERE "verseID" = 13376 AND text = 'Il re disse: "Convocate subito Aman, per fare ciò che Ester ha detto".';  -- Est 5:5 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'Infatti siamo stati venduti, io e il mio popolo, siamo stati venduti per essere distrutti, uccisi e fatti schiavi, noi e i nostri figli, per diventare servi e serve; ma io finsi di non udire, perché quel calunniatore non è degno del palazzo del re".', embedding = NULL WHERE "verseID" = 13624 AND text = 'Infatti siamo stati venduti, io e il mio popolo, siamo stati vendutiDisse il re: "Chi è costui, che ha osato fare queste cose?". per essere distrutti, uccisi e fatti schiavi, noi e i nostri figli, per diventare servi e serve; ma io finsi di non udire, perché quel calunniatore non è degno del palazzo del re".';  -- Est 7:4 GREEK
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = '<pof>Poi il re tornò dal giardino della reggia nel luogo del banchetto; intanto Aman si era lasciato cadere sul divano sul quale si trovava Ester. Allora il re esclamò: "Vuole anche fare violenza alla regina, davanti a me, in casa mia?".</pof>
<pol>Non appena questa parola fu uscita dalla bocca del re, posero un velo sulla faccia di Aman.</pol>', embedding = NULL WHERE "verseID" = 13407 AND text = 'Poi il re tornò dal giardino della reggia nel luogo del banchetto; intanto Aman si era lasciato cadere sul divano sul quale si trovava Ester. Allora il re esclamò: "Vuole anche fare violenza alla regina, davanti a me, in casa mia?". ';  -- Est 7:8 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'Lo stesso giorno, il re Artaserse donò a Ester la proprietà di Aman, il calunniatore, e Mardocheo fu chiamato dal re, perché Ester aveva rivelato che egli era legato da parentela con lei.', embedding = NULL WHERE "verseID" = 13631 AND text = 'Allora il re prese l''anello che aveva fatto ritirare ad Aman e lo diede a Mardocheo, ed Ester stabilì Mardocheo su tutte le proprietà di Aman. Lo stesso giorno, il re Artaserse donò a Ester la proprietà di Aman, il calunniatore, e Mardocheo fu chiamato dal re, perché Ester aveva rivelato che egli era legato da parentela con lei.';  -- Est 8:1 GREEK
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'Aman, infatti, il figlio di Ammedàta, l''Agaghita, il nemico di tutti i Giudei, aveva tramato contro i Giudei per distruggerli e aveva gettato il <i>pur</i>, cioè la sorte, per confonderli e farli perire.', embedding = NULL WHERE "verseID" = 13449 AND text = 'Aman, infatti, il figlio di Ammedàta, l''Agaghita, il nemico di tutti i Giudei, aveva tramato contro i Giudei per distruggerli e aveva gettato il ';  -- Est 9:24 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'Perciò quei giorni furono chiamati <i>Purìm</i> dalla parola <i>pur</i>. In conformità a tutto ciò che era contenuto in quella lettera, e in seguito a quanto avevano visto a questo proposito ed era loro accaduto,', embedding = NULL WHERE "verseID" = 13451 AND text = 'Perciò quei giorni furono chiamati ';  -- Est 9:26 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'Questi giorni devono essere commemorati e celebrati di generazione in generazione, in ogni famiglia, in ogni provincia, in ogni città; questi giorni di <i>Purìm</i> non devono cessare mai di essere celebrati fra i Giudei e il loro ricordo non dovrà mai cancellarsi fra i loro discendenti.', embedding = NULL WHERE "verseID" = 13453 AND text = 'Questi giorni devono essere commemorati e celebrati di generazione in generazione, in ogni famiglia, in ogni provincia, in ogni città; questi giorni di ';  -- Est 9:28 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'La regina Ester, figlia di Abicàil, e Mardocheo, il Giudeo, scrissero con piena autorità, per dare valore a questa loro seconda lettera relativa ai <i>Purìm</i>.', embedding = NULL WHERE "verseID" = 13454 AND text = 'La regina Ester, figlia di Abicàil, e Mardocheo, il Giudeo, scrissero con piena autorità, per dare valore a questa loro seconda lettera relativa ai ';  -- Est 9:29 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'per stabilire questi giorni di <i>Purìm</i> nelle loro date precise, come avevano stabilito loro Mardocheo, il Giudeo, e la regina Ester, e avevano disposto per sé e per i loro discendenti, in occasione del loro digiuno e del loro lamento.', embedding = NULL WHERE "verseID" = 13455 AND text = 'per stabilire questi giorni di ';  -- Est 9:31 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    UPDATE "CEI2008" SET text = 'Così la disposizione di Ester stabilì gli ordinamenti di questi <i>Purìm</i> e fu scritta in un libro.', embedding = NULL WHERE "verseID" = 13456 AND text = 'Così la disposizione di Ester stabilì gli ordinamenti di questi ';  -- Est 9:32 HEBREW
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    SELECT "verseID" INTO STRICT anchor FROM "CEI2008" WHERE "verseID" = 13631;
    INSERT INTO "CEI2008" (testament, section, book, chapter, verse, verseorigin, text, title1, title2, title3, title_position)
    SELECT testament, section, 19, 8, 2, 'GREEK', 'Allora il re prese l''anello che aveva fatto ritirare ad Aman e lo diede a Mardocheo, ed Ester stabilì Mardocheo su tutte le proprietà di Aman.', '', '', '', NULL
    FROM "CEI2008" WHERE "verseID" = anchor RETURNING "verseID" INTO new_vid;  -- Est 8:2 GREEK
    INSERT INTO cei_ord VALUES (new_vid, anchor + 0.5);
    SELECT "verseID" INTO STRICT anchor FROM "CEI2008" WHERE "verseID" = 13410;
    INSERT INTO "CEI2008" (testament, section, book, chapter, verse, verseorigin, text, title1, title2, title3, title_position)
    SELECT testament, section, 19, 8, 2, 'HEBREW', 'Il re si tolse l''anello che aveva fatto ritirare ad Aman e lo diede a Mardocheo. Ester affidò a Mardocheo l''amministrazione della casa che era stata di Aman.', '', '', '', NULL
    FROM "CEI2008" WHERE "verseID" = anchor RETURNING "verseID" INTO new_vid;  -- Est 8:2 HEBREW
    INSERT INTO cei_ord VALUES (new_vid, anchor + 0.5);
    SELECT "verseID" INTO STRICT anchor FROM "CEI2008" WHERE "verseID" = 13454;
    INSERT INTO "CEI2008" (testament, section, book, chapter, verse, verseorigin, text, title1, title2, title3, title_position)
    SELECT testament, section, 19, 9, 30, 'HEBREW', 'Si mandarono lettere a tutti i Giudei nelle centoventisette province del regno di Assuero, con parole di pace e di fedeltà,', '', '', '', NULL
    FROM "CEI2008" WHERE "verseID" = anchor RETURNING "verseID" INTO new_vid;  -- Est 9:30 HEBREW
    INSERT INTO cei_ord VALUES (new_vid, anchor + 0.5);

    IF changed <> 12 THEN
        RAISE EXCEPTION 'expected 12 damaged rows to replace, replaced %', changed;
    END IF;

    INSERT INTO cei_ord SELECT "verseID", "verseID" FROM "CEI2008" ON CONFLICT (vid) DO NOTHING;
    PERFORM bibleget_rebuild_in_order('CEI2008', 'cei_ord');
    IF (SELECT count(*) FROM "CEI2008") <> 35723 OR (SELECT max("verseID") FROM "CEI2008") <> 35723 THEN
        RAISE EXCEPTION 'unexpected row count or verseID range after the rebuild';
    END IF;

    -- Esther's index: one list for both texts (union of their verse numbers),
    -- written twice (20 entries). The first half gains 8:2 and 9:30.
    UPDATE "CEI2008_idx" i SET verses_count = x.cnt || ',' || x.cnt, verses_last = x.last || ',' || x.last
    FROM (
        SELECT string_agg(d::text, ',' ORDER BY chapter) AS cnt, string_agg(m::text, ',' ORDER BY chapter) AS last
        FROM (SELECT chapter, count(DISTINCT verse) AS d, max(verse) AS m FROM "CEI2008" WHERE book = 19 GROUP BY chapter) c
    ) x
    WHERE i.book = 19 AND i.verses_count = '22,23,15,17,14,14,10,16,31,3,22,23,15,17,14,14,10,17,32,3';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 1 THEN RAISE EXCEPTION 'CEI2008_idx Esther: unexpected verses_count'; END IF;
END
$mig$;

COMMIT;
